local k={104,240,52,25,62,201,66,133,157,116,155,148,147,14,78,42,156,90,221,92,88,147,58,112,157,188,121,250,183,21,39,60}
local s=[[]]
local t={}
local n=0
for i=1,#s,2 do
	n=n+1
	local v=tonumber(s:sub(i,i+1),16)
	t[n]=string.char(bit32.bxor(v,k[((n-1)%#k)+1]))
